@Observable @MainActor
final class Paginator<Item: Identifiable & Sendable> {
    private(set) var items: [Item] = []
    private(set) var isLoading = false
    private(set) var error: Error?
    private var cursor: String?
    private var hasMore = true
    private let fetch: (String?) async throws -> (items: [Item], next: String?)

    init(fetch: @escaping (String?) async throws -> (items: [Item], next: String?)) { self.fetch = fetch }

    func loadMoreIfNeeded(current: Item) async {
        guard hasMore, !isLoading,
              let idx = items.firstIndex(where: { $0.id == current.id }),
              idx >= items.count - 5 else { return }
        isLoading = true; defer { isLoading = false }
        do {
            let page = try await fetch(cursor)
            let known = Set(items.map(\.id))
            items += page.items.filter { !known.contains($0.id) }
            cursor = page.next; hasMore = page.next != nil; error = nil
        } catch { self.error = error }
    }
}
